"""Compiled checks for AELLO-C8-S8. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

Sparse supervision, dense grading. The shipped annotation labels a bound fraction of the training
pixels; mean intersection-over-union is taken over EVERY pixel of the private split. Every check
below runs against delivered bytes and references no unmeasured quantity, except
sparse_supervised_miou_ramp, which calls require_measured before it reads the submission and
raises ConstantUnmeasured while tests/constants.json carries nulls.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SUBMISSION = '/submission/masks.npz'

# The label domain, authored in solution/grounding.yaml and published to the agent in
# instruction.md. NUM_CLASSES is the corpus class count. IGNORE marks a pixel the sparse
# annotation never labelled; it sits OUTSIDE 0..NUM_CLASSES-1 on purpose, so that nothing can be
# scored for predicting it and it cannot be learned as a 151st class.
NUM_CLASSES = 150
IGNORE = 255

# Red line 1 forbids the graded run to READ these. The private dense masks live under the first;
# the corpus's full dense annotation lives under the second and is excluded from the agent image,
# named here so a run that reaches for it is caught by name. The agent's own sparse annotation is
# under neither, and reading THAT is the task.
PRIVATE_LABEL_ROOTS = ('tests/heldout/', 'environment/data/dense_labels/')

# Red line 2 forbids the graded run to WRITE these.
GUARDED = ('tests/', 'environment/data/dense_labels/', '/logs/verifier/')

CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "AELLO-C8-S8: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}

@check(id="checker_tree_and_graded_masks_untouched", weight=4, knockout=True, kind="integrity")
def test_checker_tree_and_graded_masks_untouched():
    touched = sorted(str(p) for p in guarded_paths_touched())
    inside = [p for p in touched if any(root in p.replace(os.sep, "/") for root in GUARDED)]
    return (not inside), evidence(target="submitted_source", guarded_roots=list(GUARDED),
                                  touched=inside[:8],
                                  reason=None if not inside
                                  else "wrote_into_the_checker_tree_or_the_graded_fold")

@check(id="dense_private_labels_unread", weight=5, knockout=True, kind="integrity")
def test_dense_private_labels_unread():
    log = paths_read()
    if log is None:
        return False, evidence(target="run_record", reason="no_read_log_produced")
    opened = sorted(str(p) for p in log
                    if any(root in str(p).replace(os.sep, "/") for root in PRIVATE_LABEL_ROOTS))
    return (not opened), evidence(target="run_record", paths_read=len(log),
                                  private_label_roots=list(PRIVATE_LABEL_ROOTS),
                                  private_label_reads=opened[:8],
                                  reason=None if not opened
                                  else "read_the_private_splits_dense_labels")

@check(id="label_domain_is_the_150_classes", weight=4, knockout=True, kind="deliverable")
def test_label_domain_is_the_150_classes():
    outside = {}
    try:
        members = load_submission()
        for name in sorted(members):
            stray = [v for v in class_ids(members[name])
                     if v != IGNORE and not 0 <= v < NUM_CLASSES]
            if stray:
                outside[name] = stray[:6]
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    ok = not outside
    return ok, evidence(classes=NUM_CLASSES, ignore_index=IGNORE,
                        scenes_out_of_domain=len(outside),
                        out_of_domain=dict(sorted(outside.items())[:4]),
                        reason=None if ok else "label_outside_the_150_class_domain")

@check(id="long_tail_not_collapsed_to_modal_class", weight=3, knockout=False, kind="deliverable")
def test_long_tail_not_collapsed_to_modal_class():
    try:
        classes = predicted_classes(load_submission())
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    ok = len(classes) > 1
    return ok, evidence(distinct_classes_predicted=len(classes), of_possible=NUM_CLASSES,
                        sample=sorted(classes)[:8],
                        reason=None if ok else "one_class_over_the_whole_split")

@check(id="mask_archive_lands", weight=4, knockout=True, kind="deliverable")
def test_mask_archive_lands():
    if not os.path.exists(SUBMISSION):
        return False, evidence(reason="submission_missing", path=SUBMISSION)
    try:
        members = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    return True, evidence(path=SUBMISSION, scenes=len(members), grids=describe(members))

@check(id="prediction_dense_despite_sparse_supervision", weight=4, knockout=False, kind="deliverable")
def test_prediction_dense_despite_sparse_supervision():
    try:
        members = load_submission()
        conceded = sum(int((members[name] == IGNORE).sum()) for name in sorted(members))
        submitted = sum(int(members[name].size) for name in sorted(members))
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    ok = conceded == 0
    return ok, evidence(conceded_pixels=conceded, submitted_pixels=submitted,
                        conceded_share=(conceded / submitted) if submitted else None,
                        reason=None if ok else "supervision_sparsity_copied_into_the_prediction")

@check(id="scene_grid_per_image_id", weight=5, knockout=True, kind="deliverable")
def test_scene_grid_per_image_id():
    manifest = scene_manifest()
    if manifest is None:
        return False, evidence(reason="graded_scene_grids_unavailable")
    try:
        members = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    missing = sorted(set(manifest) - set(members))
    unknown = sorted(set(members) - set(manifest))
    off_grid = sorted(name for name in manifest
                      if name in members and tuple(members[name].shape) != manifest[name])
    ok = not (missing or unknown or off_grid)
    return ok, evidence(graded_scenes=len(manifest), submitted_scenes=len(members),
                        missing_ids=missing[:8], unknown_ids=unknown[:8],
                        off_scene_grid=off_grid[:8],
                        reason=None if ok else "masks_do_not_match_the_graded_scene_grids")

@check(id="sparse_supervised_miou_ramp", weight=10, knockout=True, kind="outcome")
def test_sparse_supervised_miou_ramp():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    # require_measured IS THE FIRST STATEMENT, deliberately. Reading the submission first lets a
    # missing or malformed archive raise before the unmeasured signal is ever emitted, and the
    # verifier then reports gradeable true with r_det 0.0 -- which asserts the agent scored zero
    # when the truth is that this slot is not yet measurable at all.
    mean_iou = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (mean_iou - c["floor"]) / span))
    return mean_iou >= c["dichotomizing_threshold"], evidence(mean_iou=mean_iou, s_outcome=s)

@check(id="step_budget_not_truncated_by_decoder_resolution", weight=3, knockout=False, kind="process")
def test_step_budget_not_truncated_by_decoder_resolution():
    decl, why = declaration("training_schedule")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    absent = [k for k in ("planned_steps", "completed_steps", "decoder_output_stride")
              if k not in decl]
    if absent:
        return False, evidence(target="run_record", missing=absent,
                               reason="training_schedule_incomplete")
    try:
        planned = int(decl["planned_steps"])
        completed = int(decl["completed_steps"])
        stride = int(decl["decoder_output_stride"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="training_schedule_not_numeric",
                               error=str(exc))
    ok = planned > 0 and stride >= 1 and completed >= planned
    return ok, evidence(target="run_record", planned_steps=planned, completed_steps=completed,
                        decoder_output_stride=stride,
                        reason=None if ok
                        else "step_budget_truncated_at_this_decoder_resolution")

@check(id="supervision_fraction_declared_and_bounded", weight=5, knockout=True, kind="process")
def test_supervision_fraction_declared_and_bounded():
    decl, why = declaration("supervision_declaration")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    absent = [k for k in ("labelled_pixels_consumed", "pixels_total") if k not in decl]
    if absent:
        return False, evidence(target="run_record", missing=absent,
                               reason="supervision_declaration_incomplete")
    try:
        consumed = int(decl["labelled_pixels_consumed"])
        total = int(decl["pixels_total"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="supervision_declaration_not_numeric",
                               error=str(exc))
    support = sparse_labelled_support()
    if support is None:
        return False, evidence(target="run_record", reason="sparse_annotation_unavailable")
    ok = total > 0 and 0 <= consumed <= support
    return ok, evidence(target="run_record", labelled_pixels_consumed=consumed,
                        shipped_labelled_support=support, pixels_total=total,
                        declared_fraction=(consumed / total) if total > 0 else None,
                        reason=None if ok
                        else "consumed_more_labelled_pixels_than_the_shard_ships")

@check(id="unlabelled_pixels_masked_not_backpropagated", weight=4, knockout=False, kind="process")
def test_unlabelled_pixels_masked_not_backpropagated():
    policy = run_record().get("loss_policy")
    if policy is None:
        return False, evidence(target="run_record", reason="no_loss_policy_declared")
    text = str(policy).lower()
    taught = [w for w in ("background", "void", "zero_class", "class_zero",
                          "all_pixels_supervised", "dense_cross_entropy") if w in text]
    masked = any(w in text for w in ("ignore_index", "ignore index", "ignored", "masked",
                                     "mask_unlabelled", "partial_label", "label_mask"))
    ok = masked and not taught
    return ok, evidence(target="run_record", declared=str(policy)[:200],
                        unlabelled_masked=masked, dense_target_tokens=taught,
                        reason=None if ok else "unlabelled_pixels_taught_as_a_class")


def load_submission():
    """One integer mask per graded scene, keyed by ADE20K image id.

    Strict at load, so every later check reads a mask rather than re-deciding what a mask is. A
    float or boolean array is not a mask; a three-dimensional member is a probability volume and
    is NOT silently argmaxed here, because choosing the class axis for the agent would be scoring
    a submission the agent did not make.
    """
    import numpy as np
    archive = np.load(SUBMISSION, allow_pickle=False)
    members = {}
    for name in archive.files:
        mask = np.asarray(archive[name])
        if mask.ndim != 2:
            raise ValueError("member %s has ndim %d; a scene mask is 2-D" % (name, mask.ndim))
        if mask.dtype.kind not in ("i", "u"):
            raise ValueError("member %s has dtype %s; a class id is an integer"
                             % (name, mask.dtype))
        members[str(name)] = mask
    if not members:
        raise ValueError("archive carries no members; no graded scene can be scored from nothing")
    return members


def describe(members):
    """A few scene grids, so a mis-sized submission is legible in the report."""
    return ", ".join("%s %dx%d" % (name, members[name].shape[0], members[name].shape[1])
                     for name in sorted(members)[:4])


def heldout(name):
    return os.path.join(HERE, "heldout", name)


def shipped(name):
    """A path under environment/data/, which is what the agent legitimately sees."""
    return os.path.join(HERE, "..", "environment", "data", name)


def scene_manifest():
    """Graded image id -> that scene's own (height, width).

    Derived from the private masks THEMSELVES: the graded image ids ARE their member names and
    each scene's grid IS that member's shape. A second copy of the table on the checker side would
    be a thing that can drift from the labels it describes, and ADE20K grids are heterogeneous, so
    that drift would stay invisible until a mask was scored against the wrong scene. None when the
    shard has not landed.
    """
    path = heldout("graded_masks.npz")
    if not os.path.exists(path):
        return None
    import numpy as np
    truth = np.load(path, allow_pickle=False)
    return {str(name): tuple(int(d) for d in np.asarray(truth[name]).shape)
            for name in truth.files}


def sparse_labelled_support():
    """How many pixels the shipped sparse annotation actually labels.

    This is the bound the agent's declared consumption is measured against, and it is counted from
    the delivered shard rather than read from an authored constant, so the check and the corpus
    cannot drift apart. None when the shard has not landed.
    """
    path = shipped("sparse_labels.npz")
    if not os.path.exists(path):
        return None
    import numpy as np
    archive = np.load(path, allow_pickle=False)
    return int(sum(int((np.asarray(archive[name]) != IGNORE).sum()) for name in archive.files))


def class_ids(mask):
    """The distinct class ids one scene mask carries, as plain ints.

    Every numpy call lives in this module's helpers rather than in a check body, so a check reads
    as the assertion it makes and an unreadable archive surfaces once, at load, with one reason.
    """
    import numpy as np
    return [int(v) for v in np.unique(mask)]


def predicted_classes(members):
    """Distinct class ids across the whole archive, with the ignore sentinel removed."""
    seen = set()
    for name in sorted(members):
        seen.update(class_ids(members[name]))
    seen.discard(IGNORE)
    return seen


def graded_pairs():
    """Each graded image id with its submitted mask and the private dense mask beside it."""
    import numpy as np
    submitted = load_submission()
    truth = np.load(heldout("graded_masks.npz"), allow_pickle=False)
    for name in sorted(truth.files):
        if str(name) in submitted:
            yield str(name), submitted[str(name)], np.asarray(truth[name])


def measure():
    """Mean IoU accumulated PER CLASS across the whole split, then averaged over classes present.

    Per class over the split, not per image and then over images: a scene holding two classes
    would otherwise weigh as much as a scene holding forty, and the long tail is the whole point
    of this axis. Pixels the private mask marks with the ignore sentinel enter neither accumulator,
    because the corpus does not claim a class for them and nothing should be scored on them.
    """
    import numpy as np
    intersection = [0] * NUM_CLASSES
    union = [0] * NUM_CLASSES
    for name, predicted, truth in graded_pairs():
        if predicted.shape != truth.shape:
            continue
        scored = truth != IGNORE
        p = predicted[scored]
        t = truth[scored]
        for label in set(int(v) for v in np.unique(t)) | set(int(v) for v in np.unique(p)):
            if not 0 <= label < NUM_CLASSES:
                continue
            hit = p == label
            want = t == label
            intersection[label] += int((hit & want).sum())
            union[label] += int((hit | want).sum())
    present = [intersection[k] / union[k] for k in range(NUM_CLASSES) if union[k]]
    if not present:
        raise ConstantUnmeasured("no graded scene produced a defined per-class IoU")
    return float(sum(present) / len(present))


def run_record():
    path = os.path.join(HERE, "..", "run_record.json")
    if not os.path.exists(path):
        return {}
    with open(path) as handle:
        return json.load(handle)


def declaration(key):
    """An agent-authored block from the run record, parsed. Returns (block, reason).

    Absent and unparseable are kept apart deliberately: one is an agent that declared nothing and
    the other is an agent that declared something the checker could not read, and collapsing them
    would hide which.
    """
    raw = run_record().get(key)
    if raw is None:
        return None, "no_%s_in_the_run_record" % key
    try:
        return (json.loads(raw) if isinstance(raw, str) else dict(raw)), None
    except Exception as exc:
        return None, "%s_unparseable: %s" % (key, exc)


def paths_read():
    """Paths the graded run OPENED, from the record the run itself produced.

    Red line 1 forbids a read, and a post-hoc scan is the wrong instrument twice over: it cannot
    observe a read at all, and it could not separate one made during the graded run from one made
    before it. None when the run recorded no log, which is a failure and not a pass.
    """
    return run_record().get("paths_read")


def guarded_paths_touched():
    """Paths under the checker tree or the graded fold modified during the graded run."""
    return run_record().get("guarded_paths_touched", [])
